export type Arista = { origen: number; destino: number; peso: number }

export type Ciclo = { ruta: number[]; costo: number }

export type ResultadoTsp = {
  ciclos: Ciclo[]
  optimo: Ciclo | null
  tiempoMs: number
}

export const MIN_NODOS = 5
export const MAX_NODOS = 10

export function claveArista(a: number, b: number) {
  return a < b ? `${a}-${b}` : `${b}-${a}`
}

/** Construye una matriz de costos; Infinity representa una arista inexistente. */
export function construirMatrizCostos(n: number, aristas: Arista[]): number[][] {
  const matriz = Array.from({ length: n }, (_, fila) =>
    Array.from({ length: n }, (_, columna) => (fila === columna ? 0 : Infinity)),
  )

  for (const { origen, destino, peso } of aristas) {
    if (origen < 1 || destino < 1 || origen > n || destino > n) continue
    matriz[origen - 1][destino - 1] = peso
    matriz[destino - 1][origen - 1] = peso
  }
  return matriz
}

/**
 * Resuelve el TSP por fuerza bruta. Fija el nodo 1 como inicio y descarta las
 * rutas inversas equivalentes; por ello cada ciclo Hamiltoniano se cuenta una vez.
 */
export function resolverTsp(n: number, aristas: Arista[]): ResultadoTsp {
  const inicio = performance.now()
  const matriz = construirMatrizCostos(n, aristas)
  const ciclos: Ciclo[] = []
  let optimo: Ciclo | null = null
  const ruta = [0]
  const visitado = new Array(n).fill(false)
  visitado[0] = true

  const explorar = (costoAcumulado: number) => {
    const ultimo = ruta[ruta.length - 1]
    if (ruta.length === n) {
      const regreso = matriz[ultimo][0]
      if (regreso === Infinity || ruta[1] > ruta[n - 1]) return

      const ciclo = {
        ruta: [...ruta, 0].map((indice) => indice + 1),
        costo: costoAcumulado + regreso,
      }
      ciclos.push(ciclo)
      if (!optimo || ciclo.costo < optimo.costo) optimo = ciclo
      return
    }

    for (let siguiente = 1; siguiente < n; siguiente++) {
      if (visitado[siguiente]) continue
      const peso = matriz[ultimo][siguiente]
      if (peso === Infinity) continue
      visitado[siguiente] = true
      ruta.push(siguiente)
      explorar(costoAcumulado + peso)
      ruta.pop()
      visitado[siguiente] = false
    }
  }

  explorar(0)
  return { ciclos, optimo, tiempoMs: performance.now() - inicio }
}

function enteroAleatorio(minimo: number, maximo: number) {
  return Math.floor(Math.random() * (maximo - minimo + 1)) + minimo
}

/** Genera un grafo aleatorio con un ciclo base que garantiza una solución. */
export function generarGrafoAleatorio(
  n: number,
  pesoMinimo: number,
  pesoMaximo: number,
  densidad = 0.45,
): Arista[] {
  const minimo = Math.min(pesoMinimo, pesoMaximo)
  const maximo = Math.max(pesoMinimo, pesoMaximo)
  const nodos = Array.from({ length: n }, (_, indice) => indice + 1)
  const aristas: Arista[] = []
  const usadas = new Set<string>()
  const agregar = (origen: number, destino: number) => {
    const clave = claveArista(origen, destino)
    if (origen === destino || usadas.has(clave)) return
    usadas.add(clave)
    aristas.push({
      origen: Math.min(origen, destino),
      destino: Math.max(origen, destino),
      peso: enteroAleatorio(minimo, maximo),
    })
  }

  for (let indice = 0; indice < n; indice++) agregar(nodos[indice], nodos[(indice + 1) % n])
  for (let origen = 1; origen <= n; origen++) {
    for (let destino = origen + 1; destino <= n; destino++) {
      if (Math.random() < densidad) agregar(origen, destino)
    }
  }
  return aristas.sort((a, b) => a.origen - b.origen || a.destino - b.destino)
}

export function formatearRuta(ruta: number[]) {
  return ruta.join(' → ')
}

