import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { cn } from '@/lib/utils'
import { claveArista } from '@/lib/tsp'

type Props = { matriz: number[][]; rutaResaltada: number[] | null }

export function CostMatrix({ matriz, rutaResaltada }: Props) {
  const enRuta = new Set<string>()
  for (let indice = 0; rutaResaltada && indice < rutaResaltada.length - 1; indice++) {
    enRuta.add(claveArista(rutaResaltada[indice], rutaResaltada[indice + 1]))
  }

  return <Card className="min-w-0">
    <CardHeader><CardTitle>Matriz de costos</CardTitle><CardDescription>∞ indica que no existe una arista.</CardDescription></CardHeader>
    <CardContent className="overflow-x-auto"><table className="w-full border-separate border-spacing-0.5 font-mono text-sm tabular-nums"><caption className="sr-only">Matriz de costos entre nodos</caption><thead><tr><th scope="col" className="size-9" />{matriz.map((_, indice) => <th key={indice} scope="col" className="h-9 min-w-9 rounded-md bg-muted text-xs font-semibold">{indice + 1}</th>)}</tr></thead><tbody>{matriz.map((fila, i) => <tr key={i}><th scope="row" className="size-9 rounded-md bg-muted text-xs font-semibold">{i + 1}</th>{fila.map((valor, j) => <td key={j} className={cn('h-9 min-w-9 rounded-md text-center', i === j && 'bg-muted/60 text-muted-foreground', valor === Infinity && 'text-muted-foreground/50', valor !== Infinity && i !== j && 'bg-secondary/50 font-medium', i !== j && enRuta.has(claveArista(i + 1, j + 1)) && 'bg-route text-white')}>{valor === Infinity ? '∞' : valor}</td>)}</tr>)}</tbody></table></CardContent>
  </Card>
}
