'use client'

import { useState } from 'react'
import { Dices, Hand, Play, Plus, Shuffle, Trash2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Slider } from '@/components/ui/slider'
import { Separator } from '@/components/ui/separator'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { ScrollArea } from '@/components/ui/scroll-area'
import { type Arista, MAX_NODOS, MIN_NODOS, claveArista } from '@/lib/tsp'
import type { Modo } from './tsp-dashboard'

type Props = {
  nodeCount: number
  onNodeCountChange: (n: number) => void
  modo: Modo
  onModoChange: (modo: Modo) => void
  aristas: Arista[]
  onAristasChange: (aristas: Arista[]) => void
  rango: { minimo: number; maximo: number }
  onRangoChange: (rango: { minimo: number; maximo: number }) => void
  onGenerate: () => void
  onSolve: () => void
}

const selectClass = 'h-8 w-full rounded-lg border border-input bg-transparent px-2 text-sm outline-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 dark:bg-input/30'

export function ConfigPanel({ nodeCount, onNodeCountChange, modo, onModoChange, aristas, onAristasChange, rango, onRangoChange, onGenerate, onSolve }: Props) {
  const nodos = Array.from({ length: nodeCount }, (_, indice) => indice + 1)
  const [origen, setOrigen] = useState('1')
  const [destino, setDestino] = useState('2')
  const [peso, setPeso] = useState('5')
  const [error, setError] = useState<string | null>(null)

  const agregarArista = (evento: React.FormEvent) => {
    evento.preventDefault()
    const u = Number(origen)
    const v = Number(destino)
    const w = Number(peso)
    if (u === v) return setError('Los nodos de una arista deben ser distintos.')
    if (!Number.isFinite(w) || w <= 0) return setError('El peso debe ser un número positivo.')
    if (aristas.some((arista) => claveArista(arista.origen, arista.destino) === claveArista(u, v))) {
      return setError(`La arista ${Math.min(u, v)}–${Math.max(u, v)} ya existe.`)
    }
    setError(null)
    onAristasChange([...aristas, { origen: Math.min(u, v), destino: Math.max(u, v), peso: w }].sort((a, b) => a.origen - b.origen || a.destino - b.destino))
  }

  return <Card>
    <CardHeader><CardTitle>Configuración del grafo</CardTitle><CardDescription>Define entre 5 y 10 nodos.</CardDescription></CardHeader>
    <CardContent className="flex flex-col gap-5">
      <div className="flex flex-col gap-3">
        <div className="flex items-center justify-between"><Label htmlFor="node-count">Número de nodos</Label><Input id="node-count" type="number" min={MIN_NODOS} max={MAX_NODOS} value={nodeCount} onChange={(e) => { const n = Math.round(Number(e.target.value)); if (n >= MIN_NODOS && n <= MAX_NODOS) onNodeCountChange(n) }} className="h-8 w-16 text-center tabular-nums" /></div>
        <Slider aria-label="Número de nodos" min={MIN_NODOS} max={MAX_NODOS} step={1} value={[nodeCount]} onValueChange={(valor) => onNodeCountChange(Array.isArray(valor) ? valor[0] : valor)} />
      </div>
      <Separator />
      <Tabs value={modo} onValueChange={(valor) => onModoChange(valor as Modo)}>
        <TabsList className="w-full"><TabsTrigger value="aleatorio"><Dices aria-hidden="true" />Modo aleatorio</TabsTrigger><TabsTrigger value="manual"><Hand aria-hidden="true" />Modo manual</TabsTrigger></TabsList>
        <TabsContent value="aleatorio" className="flex flex-col gap-4 pt-3">
          <div className="grid grid-cols-2 gap-3"><div className="flex flex-col gap-1.5"><Label htmlFor="min-w">Peso mínimo</Label><Input id="min-w" type="number" min={1} value={rango.minimo} onChange={(e) => onRangoChange({ ...rango, minimo: Math.max(1, Number(e.target.value) || 1) })} /></div><div className="flex flex-col gap-1.5"><Label htmlFor="max-w">Peso máximo</Label><Input id="max-w" type="number" min={1} value={rango.maximo} onChange={(e) => onRangoChange({ ...rango, maximo: Math.max(1, Number(e.target.value) || 1) })} /></div></div>
          <Button variant="outline" onClick={onGenerate}><Shuffle aria-hidden="true" />Generar grafo aleatorio</Button>
        </TabsContent>
        <TabsContent value="manual" className="flex flex-col gap-3 pt-3">
          <form onSubmit={agregarArista} className="flex flex-col gap-3" noValidate><div className="grid grid-cols-3 gap-2"><div className="flex flex-col gap-1.5"><Label htmlFor="origen">Nodo 1</Label><select id="origen" className={selectClass} value={origen} onChange={(e) => setOrigen(e.target.value)}>{nodos.map((nodo) => <option key={nodo} value={nodo}>{nodo}</option>)}</select></div><div className="flex flex-col gap-1.5"><Label htmlFor="destino">Nodo 2</Label><select id="destino" className={selectClass} value={destino} onChange={(e) => setDestino(e.target.value)}>{nodos.map((nodo) => <option key={nodo} value={nodo}>{nodo}</option>)}</select></div><div className="flex flex-col gap-1.5"><Label htmlFor="peso">Peso</Label><Input id="peso" type="number" min={1} value={peso} onChange={(e) => setPeso(e.target.value)} /></div></div>{error && <p role="alert" className="text-xs text-destructive">{error}</p>}<Button type="submit" variant="outline"><Plus aria-hidden="true" />Agregar arista</Button></form>
          <div className="flex items-center justify-between pt-1"><span className="text-sm font-medium">Aristas</span><span className="text-xs text-muted-foreground tabular-nums">{aristas.length} en total</span></div>
          {aristas.length === 0 ? <p className="rounded-lg border border-dashed p-4 text-center text-xs text-muted-foreground">Aún no hay aristas.</p> : <ScrollArea className="h-52 rounded-lg border"><ul className="divide-y">{aristas.map((arista) => { const clave = claveArista(arista.origen, arista.destino); return <li key={clave} className="flex items-center justify-between px-3 py-1.5 text-sm"><span className="font-mono">{arista.origen} — {arista.destino}</span><span className="flex items-center gap-2"><span className="rounded bg-muted px-1.5 py-0.5 font-mono text-xs">peso = {arista.peso}</span><Button variant="ghost" size="icon-sm" onClick={() => onAristasChange(aristas.filter((item) => claveArista(item.origen, item.destino) !== clave))} aria-label={`Eliminar arista ${arista.origen}–${arista.destino}`}><Trash2 aria-hidden="true" /></Button></span></li> })}</ul></ScrollArea>}
        </TabsContent>
      </Tabs>
      <Separator />
      <Button size="lg" onClick={onSolve} disabled={aristas.length === 0}><Play aria-hidden="true" />Resolver TSP</Button>
    </CardContent>
  </Card>
}
