'use client'

import { useMemo } from 'react'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { type Arista, claveArista } from '@/lib/tsp'

type Props = { nodeCount: number; aristas: Arista[]; highlighted: { ruta: number[]; tipo: 'optima' | 'vistaPrevia' } | null }
const TAMANO = 440
const CENTRO = TAMANO / 2
const RADIO = 160
const RADIO_NODO = 20

function posicion(indice: number, total: number) {
  const angulo = (2 * Math.PI * indice) / total - Math.PI / 2
  return { x: CENTRO + RADIO * Math.cos(angulo), y: CENTRO + RADIO * Math.sin(angulo) }
}

export function GraphCanvas({ nodeCount, aristas, highlighted }: Props) {
  const posiciones = useMemo(() => Array.from({ length: nodeCount }, (_, indice) => posicion(indice, nodeCount)), [nodeCount])
  const aristasRuta = new Set<string>()
  for (let indice = 0; highlighted && indice < highlighted.ruta.length - 1; indice++) aristasRuta.add(claveArista(highlighted.ruta[indice], highlighted.ruta[indice + 1]))
  const colorRuta = highlighted?.tipo === 'vistaPrevia' ? 'var(--preview)' : 'var(--route)'

  return <Card className="min-w-0"><CardHeader><CardTitle>Visualización del grafo</CardTitle><CardDescription>{highlighted ? 'Ruta seleccionada resaltada.' : `${nodeCount} nodos · ${aristas.length} aristas`}</CardDescription></CardHeader><CardContent><svg viewBox={`0 0 ${TAMANO} ${TAMANO}`} className="mx-auto aspect-square w-full max-w-[520px]" role="img" aria-label={`Grafo con ${nodeCount} nodos y ${aristas.length} aristas`}>
    {aristas.map((arista) => { const a = posiciones[arista.origen - 1]; const b = posiciones[arista.destino - 1]; const resaltada = aristasRuta.has(claveArista(arista.origen, arista.destino)); return <g key={claveArista(arista.origen, arista.destino)}><line x1={a.x} y1={a.y} x2={b.x} y2={b.y} stroke={resaltada ? colorRuta : 'var(--edge)'} strokeWidth={resaltada ? 4 : 1.5} opacity={highlighted && !resaltada ? 0.45 : 1} /><rect x={(a.x + b.x) / 2 - 12} y={(a.y + b.y) / 2 - 9} width="24" height="18" rx="5" fill={resaltada ? colorRuta : 'var(--card)'} stroke={resaltada ? colorRuta : 'var(--edge)'} /><text x={(a.x + b.x) / 2} y={(a.y + b.y) / 2 + 4} textAnchor="middle" fontSize="11" fontWeight="600" fill={resaltada ? 'white' : 'var(--muted-foreground)'}>{arista.peso}</text></g> })}
    {posiciones.map((punto, indice) => <g key={indice}><circle cx={punto.x} cy={punto.y} r={RADIO_NODO} fill="var(--node)" stroke="var(--node-stroke)" strokeWidth="1.5" /><text x={punto.x} y={punto.y + 5} textAnchor="middle" fontSize="14" fontWeight="700" fill="var(--node-foreground)">{indice + 1}</text></g>)}
  </svg></CardContent></Card>
}
