'use client'

import { useMemo, useState } from 'react'
import { Route } from 'lucide-react'
import {
  type Arista,
  type ResultadoTsp,
  ARISTAS_DE_EJEMPLO,
  construirMatrizCostos,
  generarGrafoAleatorio,
  resolverTsp,
} from '@/lib/tsp'
import { ConfigPanel } from './config-panel'
import { GraphCanvas } from './graph-canvas'
import { CostMatrix } from './cost-matrix'
import { ResultsPanel } from './results-panel'

export type Modo = 'aleatorio' | 'manual'

export function TspDashboard() {
  const [nodeCount, setNodeCount] = useState(6)
  const [modo, setModo] = useState<Modo>('aleatorio')
  const [aristas, setAristas] = useState<Arista[]>(ARISTAS_DE_EJEMPLO)
  const [rango, setRango] = useState({ minimo: 1, maximo: 20 })
  const [resultado, setResultado] = useState<ResultadoTsp | null>(null)
  const [previewIndex, setPreviewIndex] = useState<number | null>(null)

  const matriz = useMemo(() => construirMatrizCostos(nodeCount, aristas), [nodeCount, aristas])

  const invalidate = () => {
    setResultado(null)
    setPreviewIndex(null)
  }

  const handleNodeCount = (n: number) => {
    setNodeCount(n)
    setAristas((previas) => previas.filter((arista) => arista.origen <= n && arista.destino <= n))
    invalidate()
  }

  const handleAristas = (siguientes: Arista[]) => {
    setAristas(siguientes)
    invalidate()
  }

  const handleGenerate = () => {
    handleAristas(generarGrafoAleatorio(nodeCount, rango.minimo, rango.maximo))
  }

  const handleSolve = () => {
    setPreviewIndex(null)
    setResultado(resolverTsp(nodeCount, aristas))
  }

  const highlighted =
    previewIndex !== null && resultado
      ? { ruta: resultado.ciclos[previewIndex].ruta, tipo: 'vistaPrevia' as const }
      : resultado?.optimo
        ? { ruta: resultado.optimo.ruta, tipo: 'optima' as const }
        : null

  return (
    <div className="min-h-dvh bg-muted/40">
      <header className="border-b bg-background">
        <div className="mx-auto flex max-w-[1500px] items-center gap-3 px-4 py-4 md:px-6">
          <div className="flex size-9 items-center justify-center rounded-lg bg-primary text-primary-foreground">
            <Route className="size-5" aria-hidden="true" />
          </div>
          <div>
            <h1 className="text-lg font-semibold leading-tight text-balance">
              Problema del Viajante (TSP)
            </h1>
          </div>
        </div>
      </header>

      <main className="mx-auto grid max-w-[1500px] gap-4 p-4 md:p-6 lg:grid-cols-[340px_1fr]">
        <aside className="lg:sticky lg:top-6 lg:self-start">
          <ConfigPanel
            nodeCount={nodeCount}
            onNodeCountChange={handleNodeCount}
            modo={modo}
            onModoChange={setModo}
            aristas={aristas}
            onAristasChange={handleAristas}
            rango={rango}
            onRangoChange={setRango}
            onGenerate={handleGenerate}
            onSolve={handleSolve}
          />
        </aside>

        <div className="flex min-w-0 flex-col gap-4">
          <div className="grid gap-4 xl:grid-cols-[1.15fr_1fr]">
            <GraphCanvas
              nodeCount={nodeCount}
              aristas={aristas}
              highlighted={highlighted}
            />
            <CostMatrix matriz={matriz} rutaResaltada={highlighted?.ruta ?? null} />
          </div>
          <ResultsPanel
            resultado={resultado}
            previewIndex={previewIndex}
            onPreview={setPreviewIndex}
          />
        </div>
      </main>
    </div>
  )
}
